window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/matematica_2025.js"]=[{"title":"Autonomia mínima para uma semana","steps":["O carro percorre 30 × 7 = 210 km por semana.","Como cada metro cúbico permite rodar 13 km, o consumo semanal é 210/13 ≈ 16,15 m³.","O menor cilindro que comporta essa quantidade é o de 17 m³. Como preço e capacidade são proporcionais, ele é o mais barato entre os adequados: C."],"alternatives":{"A":"10 m³ permitem apenas 130 km, menos que os 210 km da semana.","B":"14 m³ permitem 182 km; ainda seria necessário abastecer antes de completar a semana.","C":"17 m³ permitem 221 km, cobrindo o percurso semanal com a menor capacidade disponível suficiente.","D":"21 m³ também bastam, mas custam mais que o cilindro adequado de 17 m³.","E":"25 m³ têm autonomia suficiente, porém não representam o menor preço entre os modelos que atendem à necessidade."},"takeaway":"Em escolha mínima, calcule a necessidade e selecione o primeiro tamanho disponível que a ultrapassa.","key":"matematica:M001","area":"matematica","year":2025,"number":136,"answer":"C","subject":"Aritmética e Matemática básica","topic":"Razão, proporção e regra de três","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Porcentagem dentro de uma porcentagem","steps":["Considere 100 internautas. Pelo infográfico, 90 acessam redes sociais.","Desses 90, 60% são mulheres e 40% homens. Portanto o número de homens que acessam é 0,40 × 90 = 36.","A escolha é entre todos os internautas, logo a probabilidade é 36/100: B. Os 40% têm base apenas nos usuários de redes."],"alternatives":{"A":"30/90 não corresponde ao número de homens nem à base total de internautas escolhida pelo comando.","B":"36 em cada 100 internautas são homens que acessam redes: 90% × 40% = 36%.","C":"40/100 ignora que a proporção de homens se refere apenas aos 90% que acessam redes.","D":"40/90 mistura o percentual condicional com uma contagem, sem multiplicar corretamente as proporções.","E":"46/90 não resulta da complementação de 60% nem da combinação com os 90% de acesso."},"takeaway":"Antes de operar porcentagens, pergunte: porcentagem de qual grupo? A base final deve coincidir com o universo sorteado.","key":"matematica:M696","area":"matematica","year":2025,"number":137,"answer":"B","subject":"Probabilidade e Análise combinatória","topic":"Probabilidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Translação e projeções nos planos","steps":["A distância ao plano yz corresponde à coordenada x; ao xz, à coordenada y; ao xy, à coordenada z.","Assim, o movimento exige xnovo = x − 3, ynovo = y + 5 e znovo = z − 4. Para projetar, apague somente a coordenada perpendicular a cada plano.","Conferindo as quadrículas, as três projeções consistentes com esses deslocamentos são as de E. Não se deve trocar aproximação ao plano por aproximação a um eixo."],"alternatives":{"A":"A projeção vertical aparece mais alta que a posição obtida após diminuir z em quatro unidades.","B":"O deslocamento lateral mostrado não corresponde ao acréscimo de cinco unidades em y, além de não reunir corretamente as projeções.","C":"A posição sobre o plano yz não avança cinco unidades em y a partir da posição inicial.","D":"A projeção no plano yz também fica aquém da posição exigida pelo aumento de cinco unidades na coordenada y.","E":"As projeções conservam os pares de coordenadas da posição transladada: x diminui três, y aumenta cinco e z diminui quatro."},"takeaway":"Plano yz apaga x, plano xz apaga y e plano xy apaga z: esse esquema evita confundir eixo e plano.","key":"matematica:M497","area":"matematica","year":2025,"number":138,"answer":"E","subject":"Geometria espacial","topic":"Visualização espacial, cortes e projeções","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Cobertura dos dois lados de cada policial","steps":["Converta o raio: 1 km = 1 000 m. O comprimento da ciclovia, com π ≈ 3, é 2 × 3 × 1 000 = 6 000 m.","Conforme o esquema, cada policial protege 200 m para cada lado, totalizando um trecho de 400 m.","6 000/400 = 15 policiais, distribuídos uniformemente para não deixar lacunas: C. Com menos, a soma dos trechos protegidos seria insuficiente."],"alternatives":{"A":"Quatro policiais cobrem no máximo 1 600 m pelo modelo do item, menos que os 6 000 m da ciclovia.","B":"Oito policiais cobrem no máximo 3 200 m; ainda restariam trechos desprotegidos.","C":"Quinze trechos de 400 m completam os 6 000 m, permitindo cobertura integral sem sobra desnecessária.","D":"Trinta considera apenas 200 m por policial e ignora que ele protege os dois sentidos da ciclovia.","E":"Sessenta é excessivo: a distribuição mínima de quinze já cobre todo o comprimento."},"takeaway":"Alcance de 200 m para cada lado produz cobertura de 400 m; leia a figura antes de dividir o perímetro.","key":"matematica:M415","area":"matematica","year":2025,"number":139,"answer":"C","subject":"Geometria plana","topic":"Ângulos, circunferências e polígonos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Mediana de dez velocidades","steps":["Ordene os valores: 320, 340, 350, 360, 380, 380, 390, 390, 390 e 400 MB/s.","Como são dez valores, os termos centrais são o 5º e o 6º, ambos 380.","A mediana é (380 + 380)/2 = 380 MB/s: C. Não se calcula a média de todos nem se mantém a ordem das cidades."],"alternatives":{"A":"360 é o quarto termo da lista ordenada, não o centro de um conjunto com dez valores.","B":"370 seria a média de 360 e 380, mas esses são o quarto e o quinto termos, não os dois centrais.","C":"380 é a média do quinto e sexto termos, que coincidem, após ordenar os dados.","D":"390 é a moda e aparece várias vezes, mas frequência maior não a torna a mediana.","E":"400 é o maior valor do conjunto, não uma medida central neste caso."},"takeaway":"Para mediana, primeiro ordene; em quantidade par, use as posições n/2 e n/2 + 1.","key":"matematica:M639","area":"matematica","year":2025,"number":142,"answer":"C","subject":"Estatística","topic":"Média, mediana e moda","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Sódio total, não só por porção","steps":["O comando compara pacotes inteiros. Multiplique o sódio por porção pelo número de porções de cada pacote.","Chips: 3 × 170 = 510 mg; palitos: 4 × 501 = 2 004 mg; multigrãos: 8 × 264 = 2 112 mg; polvilho: 6 × 175 = 1 050 mg; água e sal: 5 × 166 = 830 mg.","O menor total é 510 mg, da batata chips: A. O menor valor por porção, 166 mg, não corresponde ao menor total por pacote."],"alternatives":{"A":"O pacote de chips soma 510 mg de sódio, o menor dos cinco totais calculados.","B":"Os palitos somam 2 004 mg, acima de 510 mg; não basta olhar o tamanho da porção.","C":"O multigrãos contém oito porções e totaliza 2 112 mg, o maior total do quadro.","D":"O polvilho soma 1 050 mg; o valor moderado por porção não o torna o menor pacote.","E":"Água e sal tem 166 mg por porção, mas suas cinco porções somam 830 mg, mais que os chips."},"takeaway":"Defina a unidade comparada: porção, massa de alimento e pacote inteiro podem produzir rankings diferentes.","key":"matematica:M002","area":"matematica","year":2025,"number":143,"answer":"A","subject":"Aritmética e Matemática básica","topic":"Razão, proporção e regra de três","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Classes de faces congruentes","steps":["A base comum ao prisma e ao tronco fica interna e não será pintada. Considere apenas a superfície externa.","Externamente há uma base hexagonal maior, uma menor, seis retângulos congruentes do prisma e seis trapézios congruentes do tronco.","São quatro classes de faces: dois tamanhos de hexágonos, retângulos e trapézios. Portanto quatro cores, D, e não uma cor por face."],"alternatives":{"A":"Nove cores excedem as quatro classes necessárias; faces congruentes devem receber a mesma cor.","B":"Oito também contam distinções que não existem entre faces laterais congruentes do mesmo sólido.","C":"Seis confunde a quantidade de lados das bases ou faces laterais com a quantidade de tipos de faces.","D":"Quatro cores distinguem base maior, base menor, retângulos laterais e trapézios laterais.","E":"Três cores identificariam indevidamente as duas bases hexagonais, que têm tamanhos diferentes e não são congruentes."},"takeaway":"Em sólidos justapostos, retire faces internas e conte classes de congruência, não apenas tipos de polígonos.","key":"matematica:M498","area":"matematica","year":2025,"number":144,"answer":"D","subject":"Geometria espacial","topic":"Visualização espacial, cortes e projeções","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Decrescimento seguido de estabilização","steps":["Entre t₁ e t₂, a curva desce de f₁ para f₂: a frequência respiratória diminui.","A partir de t₂, o gráfico é horizontal e a frequência permanece no patamar f₂.","O comportamento é o descrito em D. Uma grandeza diminuir não basta para ser inversamente proporcional ao tempo."],"alternatives":{"A":"A frequência não é constante durante todo o intervalo posterior a t₁; ela cai até t₂.","B":"Proporcionalidade direta exigiria relação f = kt, incompatível com a queda e a estabilização mostradas.","C":"Proporcionalidade inversa exigiria produto ft constante, o que não se verifica nem é indicado pela curva.","D":"A opção descreve corretamente a queda até t₂ e a constância a partir desse instante.","E":"Após t₂ não há nova diminuição; além disso, o trecho curvo não indica decrescimento proporcional uniforme."},"takeaway":"Gráfico decrescente não é automaticamente proporcionalidade inversa. Verifique a forma e os diferentes intervalos.","key":"matematica:M338","area":"matematica","year":2025,"number":145,"answer":"D","subject":"Álgebra e Funções","topic":"Leitura e transformação de gráficos de funções","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Subtração com casas decimais","steps":["Escreva as duas medidas com a mesma quantidade de casas decimais: 10,00 s e 9,58 s.","A diferença é 10,00 − 9,58 = 0,42 s. Em centésimos, são 1 000 − 958 = 42 centésimos.","Confirme somando: 9,58 + 0,42 = 10,00. A resposta é B; não há conversão de unidade, pois ambas as medidas estão em segundos."],"alternatives":{"A":"0,02 s faria a soma chegar apenas a 9,60 s, não a 10,00 s.","B":"0,42 s completa exatamente a diferença entre 9,58 s e a referência de 10,00 s.","C":"0,52 s levaria a 10,10 s, ultrapassando a referência em um décimo.","D":"1,02 s produziria 10,60 s, não a marca de referência.","E":"1,42 s produziria 11,00 s; inclui um segundo a mais na diferença."},"takeaway":"Alinhe as vírgulas e confira uma subtração pela soma, especialmente quando há empréstimo entre casas decimais.","key":"matematica:M169","area":"matematica","year":2025,"number":146,"answer":"B","subject":"Aritmética e Matemática básica","topic":"Operações, frações e sistemas de numeração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Comparação de distâncias em escalas diferentes","steps":["Cada indicação em centímetros está na tela; para obter a distância real, multiplique pelo denominador da escala.","I: 9 × 100 = 900 cm; II: 5 × 300 = 1 500 cm; III: 5 × 600 = 3 000 cm; IV: 3 × 700 = 2 100 cm; V: 2 × 1 000 = 2 000 cm.","A maior distância real é 3 000 cm, ou 30 m, do deslocamento III: C. A maior imagem na tela não precisa representar o maior percurso."],"alternatives":{"A":"I corresponde a 9 m, apesar de ser a maior medida desenhada; sua escala tem denominador menor.","B":"II corresponde a 15 m, inferior aos 30 m do deslocamento III.","C":"III corresponde a 5 × 600 = 3 000 cm, o maior dos percursos reais.","D":"IV corresponde a 21 m; o denominador grande não supera o produto de III.","E":"V corresponde a 20 m; a escala de maior denominador, sozinha, não garante o maior deslocamento."},"takeaway":"Em escala 1:n, distância real = distância no desenho × n; compare somente depois de converter todas.","key":"matematica:M114","area":"matematica","year":2025,"number":148,"answer":"C","subject":"Aritmética e Matemática básica","topic":"Escalas e conversões de unidades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Vértices pela relação de Euler","steps":["Na planificação, conte as faces: 25 triângulos, cinco quadrados, um pentágono e um decágono, totalizando F = 32.","A soma dos lados das faces é 25 × 3 + 5 × 4 + 5 + 10 = 110. Cada aresta pertence a duas faces, portanto E = 55.","Para o poliedro convexo, V − E + F = 2. Logo V = 2 + 55 − 32 = 25: B. Vértices duplicados na planificação devem ser identificados na montagem."],"alternatives":{"A":"21 não satisfaz a relação de Euler com as 32 faces e 55 arestas do sólido.","B":"25 é o resultado de 2 + 55 − 32, correspondendo aos vértices do poliedro montado.","C":"55 é o número de arestas, obtido ao dividir por dois a soma dos lados das faces.","D":"80 não corresponde aos vértices distintos após a montagem; elementos da planificação podem se sobrepor.","E":"110 é a soma de incidências de lados nas faces, não o número de vértices do sólido."},"takeaway":"Em poliedro convexo, uma planificação permite contar faces e arestas antes de obter vértices por Euler.","key":"matematica:M499","area":"matematica","year":2025,"number":149,"answer":"B","subject":"Geometria espacial","topic":"Visualização espacial, cortes e projeções","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Montagem de um código por blocos","steps":["Separe o formato em blocos: um dígito de andar, dois de setor, três de funcionário e um de turno.","Os dados são 2 | 08 | 109 | 0, pois a visita ocorre às 10 horas da manhã.","Concatenando sem trocar a ordem nem apagar o zero do setor, obtemos 2081090: D. O código não é uma soma entre os blocos."],"alternatives":{"A":"0109082 não começa pelo andar 2 e não respeita a sequência de campos definida.","B":"0281090 inicia com 0 e 28 no setor, omitindo a codificação correta do andar e do setor 08.","C":"1010982 também não começa pelo andar e altera o posicionamento dos blocos.","D":"2081090 corresponde exatamente a 2, 08, 109 e 0, nos comprimentos previstos.","E":"2810910 elimina o zero necessário em 08 e desloca os demais campos, alterando a identificação."},"takeaway":"Em códigos, zeros à esquerda de um bloco têm função de posição e não podem ser apagados.","key":"matematica:M170","area":"matematica","year":2025,"number":151,"answer":"D","subject":"Aritmética e Matemática básica","topic":"Operações, frações e sistemas de numeração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma distribuição correta entre 4!","steps":["Os quatro celulares são distintos e a entrega aleatória sem reposição produz 4! = 24 distribuições equiprováveis.","Apenas uma atribui cada aparelho ao seu dono. Logo a probabilidade conjunta é 1/24.","Também se pode multiplicar as chances condicionais: (1/4)(1/3)(1/2)(1) = 1/24, alternativa D. As quatro entregas não são independentes."],"alternatives":{"A":"1/2 superestima a chance: existem 24 distribuições, e só uma deixa todos corretos.","B":"1/10 não corresponde ao total de permutações dos quatro objetos distintos.","C":"1/16 não contabiliza corretamente a distribuição sem reposição dos quatro celulares.","D":"1/24 representa uma única permutação correta entre as 24 possíveis.","E":"1/256 é (1/4)⁴ e trataria cada entrega como independente, ignorando que celulares já entregues não voltam ao sorteio."},"takeaway":"Em sorteio sem reposição, as probabilidades sucessivas mudam; permutação e produto condicional devem concordar.","key":"matematica:M697","area":"matematica","year":2025,"number":152,"answer":"D","subject":"Probabilidade e Análise combinatória","topic":"Probabilidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A diagonal como mediatriz","steps":["Os pontos equidistantes dos vilões V e T pertencem à mediatriz de VT. No quadrado, essa reta é a outra diagonal, SU, que passa por S(6,2).","O vetor SV = (2,4). Rotacionando-o 90° para alcançar T, temos ST = (−4,2), logo T = (2,4) e U = (4,8).","A inclinação de SU é (8 − 2)/(4 − 6) = −3. Usando S: 2 = −3 × 6 + b, então b = 20 e y = −3x + 20: A."],"alternatives":{"A":"A reta tem inclinação −3 e passa por S(6,2), sendo a diagonal mediatriz de VT.","B":"y = −3x + 16 nem passa pelo ponto inicial S: para x = 6, fornece y = −2.","C":"y = −3x − 20 também não passa por S; o termo independente tem sinal e valor incompatíveis.","D":"y = 3x + 16 tem inclinação positiva, contrária à diagonal SU representada.","E":"y = 3x − 16 passa por S, mas tem inclinação errada e não mantém equidistância dos dois vilões ao longo do percurso."},"takeaway":"Passar pelo ponto inicial é necessário, mas não suficiente: a trajetória equidistante é a mediatriz dos dois pontos fixos.","key":"matematica:M535","area":"matematica","year":2025,"number":153,"answer":"A","subject":"Geometria analítica","topic":"Plano cartesiano, distâncias e retas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Estoque total comparado à demanda","steps":["Some as duas barras de cada gênero: autores brasileiros e estrangeiros pertencem ao mesmo estoque disponível.","Ficção: 80 + 120 = 200, demanda 160; autoajuda: 50 + 80 = 130, demanda 135; romance: 40 + 105 = 145, demanda 140; biografia: 45 + 50 = 95, demanda 80.","Só autoajuda tem déficit, de cinco exemplares. Portanto C. Maior demanda não implica falta quando o estoque também é grande."],"alternatives":{"A":"Ficção tem a maior demanda, mas seus 200 exemplares superam os 160 solicitados.","B":"A menor demanda de biografias não justifica reposição: há 95 exemplares para demanda de 80.","C":"Autoajuda tem 130 exemplares para demanda de 135, sendo o único gênero com falta.","D":"Mesmo com estoque total relativamente menor, biografia ainda atende à demanda; falta é diferença, não posição no ranking.","E":"O romance tem apenas 40 exemplares brasileiros, mas o estoque conjunto de 145 atende aos 140 demandados."},"takeaway":"Compare demanda com o estoque relevante completo; não escolha pelo maior ou menor valor isolado de uma coluna.","key":"matematica:M550","area":"matematica","year":2025,"number":154,"answer":"C","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Cargos distintos e exclusão dos cônjuges","steps":["Há 20 pessoas para presidente. Escolhido alguém, seu cônjuge não pode ocupar outro cargo.","Para secretário restam 18 pessoas de nove casais. Para tesoureiro, retiram-se os dois casais já representados, restando 16 pessoas.","Como os cargos são distintos, multiplique as escolhas ordenadas: 20 × 18 × 16 = 5 760 diretorias, expressão da alternativa B."],"alternatives":{"A":"10 × 9 × 8 escolhe apenas casais para os cargos e não escolhe qual pessoa de cada casal os ocupa.","B":"20 × 18 × 16 considera a identidade das pessoas, os cargos diferentes e a proibição de repetir um casal.","C":"20 × 19 × 18 retira apenas a pessoa escolhida, permitindo indevidamente seu cônjuge no próximo cargo.","D":"10 × 9 × 8 × 2 escolhe a pessoa em apenas um dos casais; são necessários três fatores 2.","E":"O produto 20 × 18 × 16 já distingue os membros de cada casal; multiplicar de novo por 2 duplica a contagem."},"takeaway":"Restrição por casal retira duas pessoas a cada cargo preenchido. Cargos diferentes tornam a ordem relevante.","key":"matematica:M750","area":"matematica","year":2025,"number":155,"answer":"B","subject":"Probabilidade e Análise combinatória","topic":"Contagem e análise combinatória","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Escala exige unidades iguais","steps":["A medida do esboço é 20 cm e a correspondente na obra é 30 m.","Converta 30 m em 3 000 cm. A razão desenho/obra é 20/3 000 = 1/150.","A escala é 1:150: E. Não se usam áreas, pois a comparação é entre comprimentos correspondentes."],"alternatives":{"A":"1:1,5 resulta de comparar 20 cm com 30 m sem igualar as unidades.","B":"1:2,25 não é a razão linear 20/3 000; a escala não pede elevar um fator ao quadrado.","C":"1:10 faria 20 cm corresponderem a 200 cm, ou 2 m, não a 30 m.","D":"1:100 faria a medida real ser 2 000 cm, equivalentes a 20 m.","E":"1:150 transforma 20 cm em 3 000 cm, exatamente os 30 m informados."},"takeaway":"Escreva desenho/real em uma única unidade antes de simplificar a escala.","key":"matematica:M115","area":"matematica","year":2025,"number":156,"answer":"E","subject":"Aritmética e Matemática básica","topic":"Escalas e conversões de unidades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"“Vezes” define uma razão","steps":["O texto afirma que a concentração em trabalho T é 1,59 vezes a concentração em folga F.","Isso se escreve T = 1,59F, uma relação multiplicativa, e não T = F + 1,59.","Dividindo por F, obtemos T/F = 1,59, alternativa C. A razão indica aumento relativo de 59%, não de 159% sobre F."],"alternatives":{"A":"T = 1,59 + F trata o fator multiplicativo como aumento absoluto, com unidades indevidamente misturadas.","B":"F = 1,59 + T também é aditivo e ainda coloca a folga como maior valor.","C":"T/F = 1,59 é equivalente a T = 1,59F e reproduz a comparação multiplicativa do texto.","D":"F/T = 1,59 inverte a relação; o correto seria F/T = 1/1,59.","E":"F × T = 1,59 estabelece um produto constante, não a proporção direta informada."},"takeaway":"“A é k vezes B” significa A/B = k. Diferencie fator total e percentual de aumento.","key":"matematica:M259","area":"matematica","year":2025,"number":157,"answer":"C","subject":"Álgebra e Funções","topic":"Função afim e modelos lineares","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Receita necessária para atingir o lucro","steps":["O novo seguro por veículo é 36 × 1,20 = R$ 43,20; para 120 veículos, o custo é 120 × 43,20 = R$ 5 184,00.","A despesa total é 14 240 + 5 184 = R$ 19 424,00. Para obter lucro de R$ 10 000,00, a receita precisa ser R$ 29 424,00.","Dividindo pelas 120 mensalidades: 29 424/120 = R$ 245,20, alternativa C. O reajuste de 20% se aplica ao seguro, não a todas as despesas."],"alternatives":{"A":"R$ 185,60 arrecadariam R$ 22 272,00, gerando lucro de apenas R$ 2 848,00 após as novas despesas.","B":"R$ 226,09 não arrecadam os R$ 29 424,00 necessários para cobrir despesas e o lucro pretendido.","C":"R$ 245,20 × 120 = R$ 29 424,00; retirando R$ 19 424,00, restam exatamente R$ 10 000,00.","D":"R$ 268,93 produziriam receita superior à necessária; o item pede o valor correspondente ao lucro estipulado.","E":"R$ 285,60 também excedem o valor exigido; não se deve aplicar o reajuste do seguro à mensalidade inteira."},"takeaway":"Receita = despesas + lucro. Separe custo por unidade e custo fixo antes de dividir pelo número de clientes.","key":"matematica:M225","area":"matematica","year":2025,"number":158,"answer":"C","subject":"Álgebra e Funções","topic":"Equações, sistemas e inequações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Centímetro cúbico equivale a mililitro","steps":["Use a equivalência 1 cm³ = 1 mL. O pote contém, portanto, 20 000 mL.","Cada taça recebe 250 mL. A quantidade é 20 000/250 = 80.","A resposta é D. Como a divisão é exata, não sobra volume nesse modelo; 80 × 250 = 20 000 confirma o resultado."],"alternatives":{"A":"Cinco taças usariam apenas 1 250 mL, uma pequena parte do pote.","B":"Oito taças usariam 2 000 mL; falta um fator dez para esgotar 20 000 mL.","C":"Cinquenta taças consumiriam 12 500 mL, deixando sorvete no pote.","D":"Oitenta porções de 250 mL completam exatamente os 20 000 mL disponíveis.","E":"Oitocentas taças exigiriam 200 000 mL, dez vezes o volume do pote."},"takeaway":"Memorize as equivalências úteis: 1 cm³ = 1 mL e 1 dm³ = 1 L; depois divida volumes na mesma unidade.","key":"matematica:M116","area":"matematica","year":2025,"number":159,"answer":"D","subject":"Aritmética e Matemática básica","topic":"Escalas e conversões de unidades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Tangente: centro e assíntotas","steps":["As assíntotas são T = (5 − 2π)/2 e T = (5 + 2π)/2, com distância 2π. Como a tangente tem período π, em tg[p(T + m)] temos p = 1/2 para o ramo crescente mostrado.","O centro do ramo está em T = 5/2 = 2,5. Portanto o argumento se anula em T − 5/2, e m = −5/2.","No centro, D = 30 e tg(0) = 0, logo k = 30. Assim D = 30 + tg[(1/2)(T − 5/2)], alternativa E, que também reproduz as assíntotas."],"alternatives":{"A":"A expressão usa deslocamento vertical 2,5 e fator 30 no argumento; não passa pelo centro (2,5;30) como o gráfico exige.","B":"O deslocamento vertical 4 e a frequência do argumento 30 são incompatíveis com o centro e o período mostrados.","C":"O fator 2,5 não produz o intervalo 2π entre assíntotas, e o deslocamento vertical também não é 30.","D":"O fator 1/2 e o deslocamento vertical estão adequados, mas T − 5 centra o ramo em T = 5, não em 2,5.","E":"A expressão tem centro (2,5;30) e assíntotas em 2,5 ± π, exatamente os valores apresentados."},"takeaway":"Na tangente transformada, encontre primeiro o centro e a distância entre assíntotas; só depois ajuste os parâmetros.","key":"matematica:M789","area":"matematica","year":2025,"number":160,"answer":"E","subject":"Trigonometria","topic":"Funções trigonométricas e fenômenos periódicos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Percurso inverso com pontos cardeais","steps":["João sai da esquina nordeste, anda a oeste pelo próprio quarteirão, vira ao norte por três quarteirões e depois segue a oeste até a casa A.","Comece por A e desfaça o percurso: vá a leste por dois quarteirões, depois ao sul por três, chegando ao lado oeste do quarteirão de João.","Ande então a leste pelo quarteirão para recuperar sua esquina nordeste. O quarteirão é P, alternativa A. O caminho inverso inverte a ordem dos movimentos."],"alternatives":{"A":"P fica na linha três quarteirões ao sul de A e na posição horizontal compatível com a volta dos dois quarteirões a oeste.","B":"Q está acima de A; contradiz o trecho de três quarteirões para o norte ao sair da casa de João.","C":"R está demasiado a oeste: a direção final do percurso não permitiria alcançar A como descrito.","D":"S está aproximadamente na linha de A, sem os três quarteirões de diferença norte–sul.","E":"T fica um quarteirão mais a leste que a posição obtida ao refazer as distâncias indicadas."},"takeaway":"Quando há várias curvas, refaça o caminho de trás para frente e mantenha fixos norte, sul, leste e oeste.","key":"matematica:M429","area":"matematica","year":2025,"number":161,"answer":"A","subject":"Geometria plana","topic":"Simetria e transformações geométricas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma escala comum para os dois gráficos","steps":["No gráfico de barras, conte intervalos iguais: futebol soma 7 + 6 + 5 = 18 unidades; vôlei, 3 + 3 + 4 = 10; basquete, 1 + 3 + 4 = 8.","O gráfico de setores informa 80 alunos no basquete. Logo cada unidade vertical equivale a 80/8 = 10 alunos.","O total é (18 + 10 + 8) × 10 = 360 alunos: B. Confirme: os 180 do futebol ocupam metade do gráfico circular."],"alternatives":{"A":"720 duplica o total obtido; os 80 do basquete correspondem a oito, não quatro unidades das barras.","B":"360 resulta da calibração da escala com os 80 do basquete e da soma de todas as modalidades.","C":"320 não corresponde às 36 unidades totais, cada uma com dez estudantes.","D":"288 resulta de uma escala incompatível com a indicação de 80 estudantes no basquete.","E":"240 deixa de contabilizar corretamente todas as séries e modalidades; o gráfico de futebol sozinho já soma 180."},"takeaway":"Use o valor conhecido de um gráfico para calibrar a escala do outro; depois confira com uma proporção independente.","key":"matematica:M551","area":"matematica","year":2025,"number":163,"answer":"B","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Corrigir a rota sem refazer todo o caminho","steps":["Os dois segundos deslocamentos são iguais, 2v para leste, e se cancelam na comparação. Logo TR tem o mesmo vetor de SQ, entre os pontos alcançados após as quatro horas iniciais.","Os segmentos PQ e PS medem 4v e formam ângulo menor de 130°. Pela lei dos cossenos, TR² = (4v)² + (4v)² − 2(4v)² cos130° = 32v²(1 + 0,64) = 52,48v².","Assim, tempo = TR/v = √52,48 ≈ 7,245 h, cerca de 7 h 15 min. A diferença de posições aponta para sudeste, azimute 135: A."],"alternatives":{"A":"A direção sudeste 135 e o tempo aproximado de 7 h 15 min correspondem ao vetor corretivo e à lei dos cossenos.","B":"O tempo é adequado, mas 45 aponta para nordeste, e o destino está a sudeste do ponto T.","C":"A direção 135 é adequada, mas 12 horas não decorrem da distância retilínea calculada.","D":"135 está correto, porém 6 horas subestimam √52,48 horas necessário à mesma velocidade.","E":"45 aponta ao quadrante errado e 6 horas também subestimam a duração da correção."},"takeaway":"Deslocamentos iguais podem ser cancelados numa diferença vetorial. Converta a parte decimal da hora multiplicando por 60.","key":"matematica:M780","area":"matematica","year":2025,"number":164,"answer":"A","subject":"Trigonometria","topic":"Razões trigonométricas e aplicações geométricas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Desvio padrão pequeno garante concentração","steps":["O grupo 4 tem média 25 e desvio padrão 1. Com 11 pessoas, a soma dos quadrados dos desvios é no máximo 11, conforme a convenção de desvio usada.","Qualquer idade fora de 20–30 teria distância maior que 5 da média e, sozinha, quadrado do desvio maior que 25, impossível nesse grupo.","Assim todas as idades do grupo 4 estão no intervalo, garantindo a maioria: D. Média, mediana ou moda 25 isoladamente não asseguram essa concentração."],"alternatives":{"A":"O grupo 1 tem média 25, mas desvio 10 permite grande dispersão; não garante maioria no intervalo de dez anos.","B":"Mediana 25 no grupo 2 não impede que cinco idades sejam menores que 20 e cinco maiores que 30.","C":"Moda 25 só indica a idade mais frequente, que pode aparecer em menos de seis das onze pessoas.","D":"O desvio padrão 1 junto da média 25 obriga as idades a permanecer próximas de 25, todas entre 20 e 30.","E":"Saber que o mínimo é 20 e o máximo 35 não informa quantas das demais idades ultrapassam 30."},"takeaway":"Medida central não garante concentração. Uma medida de dispersão pode permitir uma conclusão que média, moda ou mediana sozinhas não dão.","key":"matematica:M691","area":"matematica","year":2025,"number":165,"answer":"D","subject":"Estatística","topic":"Dispersão e interpretação de dados","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pace é tempo total dividido pela distância","steps":["Para pace de 281 s/km em 5 km, o tempo total deve ser 281 × 5 = 1 405 s.","Até o quarto quilômetro, o corredor gastou 1 132 s. Restam 1 405 − 1 132 = 273 s para o quinto trecho.","No quarto trecho ele gastou 288 s. A redução necessária é 288 − 273 = 15 s: E. O alvo não é correr apenas o último quilômetro em 281 s."],"alternatives":{"A":"Reduzir só 1 s deixaria o último trecho em 287 s e o total em 1 419 s, acima do alvo.","B":"Reduzir 2 s ainda produziria 286 s no trecho final e não compensaria o tempo acumulado.","C":"Reduzir 8 s daria 280 s, mas o total seria 1 412 s, maior que 1 405 s.","D":"Reduzir 9 s daria 279 s, ainda seis segundos além do tempo final necessário.","E":"Reduzir 15 s deixa o trecho em 273 s e completa 1 405 s, exatamente o pace de 281 s/km."},"takeaway":"Meta de média exige compensar o acumulado: calcule o total-alvo antes de descobrir o desempenho da etapa final.","key":"matematica:M004","area":"matematica","year":2025,"number":166,"answer":"E","subject":"Aritmética e Matemática básica","topic":"Razão, proporção e regra de três","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Gasto: distância dividida pelo rendimento","steps":["Cada combustível foi utilizado em 120 km. A 60 km/h, os gráficos indicam 10 km/m³ para GNV e 8 km/L para gasolina.","GNV: 120/10 = 12 m³, custando 12 × 2 = R$ 24. Gasolina: 120/8 = 15 L, custando 15 × 3 = R$ 45.","A diferença é 45 − 24 = R$ 21, alternativa D. O preço unitário deve ser combinado ao rendimento de cada combustível."],"alternatives":{"A":"R$ 4 não resulta da comparação dos gastos de R$ 45 e R$ 24 nas duas metades do trajeto.","B":"R$ 8 também não corresponde à diferença dos custos após considerar o rendimento de cada combustível.","C":"R$ 14 subestima a diferença; gasolina exige 15 litros e GNV exige 12 metros cúbicos.","D":"R$ 21 é a diferença entre R$ 45 de gasolina e R$ 24 de GNV.","E":"R$ 30 não é a diferença pedida; comparar apenas preços por unidade ignora o consumo por distância."},"takeaway":"Quando o rendimento é km por unidade de combustível, consumo = distância/rendimento; só depois multiplique pelo preço.","key":"matematica:M808","area":"matematica","year":2025,"number":167,"answer":"D","subject":"Matemática financeira","topic":"Descontos, preços e comparação de propostas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Comparação de pacotes completos","steps":["O custo é 20 vezes o preço da aula teórica mais 10 vezes o da prática, acrescido do aluguel do veículo.","I: 20 × 10 + 10 × 80 + 400 = R$ 1 400; II: 20 × 30 + 10 × 50 + 200 = R$ 1 300.","III: 20 × 20 + 10 × 40 + 400 = R$ 1 200. O menor total é o da escola III: E. Os três produtos devem ser contratados no mesmo lugar."],"alternatives":{"A":"O total da escola I está calculado corretamente, mas R$ 1 400 não é o menor entre os três.","B":"R$ 280 soma preços unitários e aluguel da escola II, sem multiplicar pelo número de aulas.","C":"A escola II custa mesmo R$ 1 300, porém a III oferece total menor, de R$ 1 200.","D":"R$ 460 é a soma de uma aula teórica, uma prática e aluguel da escola III, não o pacote completo.","E":"A escola III totaliza R$ 1 200 e é a opção mais econômica para todos os produtos no mesmo estabelecimento."},"takeaway":"Preço unitário barato não decide sozinho: modele o pacote com suas quantidades e custos fixos.","key":"matematica:M809","area":"matematica","year":2025,"number":168,"answer":"E","subject":"Matemática financeira","topic":"Descontos, preços e comparação de propostas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Produção não é produtividade","steps":["Produção = área em hectares × produtividade em sacas por hectare. Cada saca pesa 50 kg, ou 0,05 t.","Calcule por safra: 200 × 40 × 0,05 = 400 t; 220 × 30 × 0,05 = 330 t; 250 × 45 × 0,05 = 562,5 t; depois 562,5 t; e 200 × 50 × 0,05 = 500 t.","A sequência 400; 330; 562,5; 562,5; 500 aparece no gráfico A. O patamar das duas safras centrais é uma conferência útil."],"alternatives":{"A":"O gráfico apresenta exatamente os cinco produtos área × produtividade convertidos para toneladas.","B":"Os valores somam área e produtividade, grandezas com unidades diferentes, em vez de calcular a produção.","C":"Os pontos repetem a produtividade em sacas por hectare, não a produção total em toneladas.","D":"Os valores deixam de incorporar corretamente a massa de 50 kg de cada saca à conversão para toneladas.","E":"Os pontos representam as áreas cultivadas, não o total de soja produzido."},"takeaway":"Confira unidades: hectare × saca/hectare × tonelada/saca = tonelada. Essa análise revela qual operação usar.","key":"matematica:M552","area":"matematica","year":2025,"number":169,"answer":"A","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Garrafas deslocam volume de água","steps":["A caixa enche até 2 dm e tem volume 2,5 × 1,5 × 2 = 7,5 dm³ = 7,5 L.","Para manter pelo menos 5 L de água, as garrafas podem deslocar no máximo 2,5 L. Cada uma ocupa 0,3 L.","Como n ≤ 2,5/0,3 ≈ 8,33 e n deve ser inteiro, cabem no máximo oito garrafas: B. Restam 7,5 − 2,4 = 5,1 L; nove deixariam apenas 4,8 L."],"alternatives":{"A":"Dez garrafas deslocam 3 L, deixando 4,5 L de água, abaixo do mínimo exigido.","B":"Oito deslocam 2,4 L e mantêm 5,1 L; a nona já reduziria o volume abaixo de 5 L.","C":"Quatro preservam o funcionamento, mas não são a quantidade máxima: ainda é possível colocar mais quatro.","D":"Três também deixam sobra de volume deslocável e não atendem ao pedido de máximo.","E":"Duas são insuficientes para maximizar a economia permitida; oito ainda respeitam o mínimo de água."},"takeaway":"Quando a boia fixa a altura, objetos submersos substituem água por seu volume externo. Em máximo inteiro, arredonde para baixo.","key":"matematica:M437","area":"matematica","year":2025,"number":170,"answer":"B","subject":"Geometria espacial","topic":"Volumes e capacidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A caixa deve comportar a maior torta","steps":["Para atender a todos os modelos, use o maior raio, 16 cm. A torta terá diâmetro 32 cm.","A folga lateral de 1 cm em cada lado exige lado interno da caixa de 32 + 2 = 34 cm. A altura original de 7 cm já permite 6 cm de torta e 1 cm de folga superior.","O aumento da aresta em relação à caixa original é 34 − 14 = 20 cm: E. A pergunta pede aumento, não a dimensão final."],"alternatives":{"A":"Aumentar 4 cm levaria o lado a 18 cm, insuficiente até para o diâmetro da menor torta, 24 cm.","B":"Aumentar 12 cm levaria o lado a 26 cm, adequado à menor torta com folgas, mas não à maior.","C":"Aumentar 16 cm levaria o lado a 30 cm, menor que o diâmetro máximo de 32 cm.","D":"Aumentar 18 cm daria 32 cm, sem deixar as folgas de 1 cm de cada lado da maior torta.","E":"Aumentar 20 cm produz lado 34 cm, que acomoda diâmetro de 32 cm com as duas folgas laterais."},"takeaway":"Dimensione pelo maior objeto e some folgas dos dois lados. Separe dimensão final de aumento solicitado.","key":"matematica:M500","area":"matematica","year":2025,"number":171,"answer":"E","subject":"Geometria espacial","topic":"Visualização espacial, cortes e projeções","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O pico ocorre antes do final das dez horas","steps":["A pressão é P = 4 log₁₀[K(t + 1)(19 − t)]. No intervalo 0 ≤ t ≤ 10, o fator temporal é f(t) = −t² + 18t + 19.","A parábola tem máximo no vértice t = −18/(−2) = 9 h; f(9) = 100. Como o logaritmo é crescente, a maior pressão é 4 log₁₀(100K).","Imponha 4 log₁₀(100K) ≤ 10: 100K ≤ 10^2,5, logo K ≤ 10^0,5. O maior valor é A. Usar somente t = 10 perderia o pico em 9 h."],"alternatives":{"A":"10^0,5 é o maior K que limita o máximo da pressão a 10 atm durante todo o intervalo.","B":"10⁸ é muito maior que o limite; no pico a pressão seria 4 log₁₀(10¹⁰) = 40 atm.","C":"10^2,5/84 usa um fator temporal inferior ao máximo de 100, permitindo ultrapassar o limite no vértice.","D":"10^2,5/99 corresponde ao fator em 10 h, mas o máximo ocorre em 9 h, quando esse K produz pressão maior que 10 atm.","E":"25 × 10⁻² = 0,25 respeita o limite, mas não é o maior valor possível, pois 10^0,5 ≈ 3,16 também o respeita."},"takeaway":"Quando uma condição deve valer em todo o intervalo, encontre o máximo da função antes de testar o ponto final.","key":"matematica:M301","area":"matematica","year":2025,"number":172,"answer":"A","subject":"Álgebra e Funções","topic":"Funções exponenciais e logaritmos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Dois semicírculos podem exigir menos escavação","steps":["O projeto 1 tem diâmetros 12 m e 6 m, portanto raios 6 m e 3 m. Sua área total é (π/2)(6² + 3²).","Com π ≈ 3, A₁ = (3/2) × 45 = 67,5 m². O projeto 2 tem diâmetro 3 + 6 + 6 + 3 = 18 m e raio 9 m, então A₂ = (3/2) × 81 = 121,5 m².","Como os túneis têm a mesma extensão, a menor área transversal implica menor volume retirado. Escolhe-se o projeto 1, com 67,5 m²: A."],"alternatives":{"A":"O projeto 1 exige 67,5 m², menos que os 121,5 m² do projeto 2, minimizando o volume de escavação.","B":"121,5 m² é a área do projeto 2, mas ela é maior, não a menor procurada.","C":"135 m² esquece o fator 1/2 e calcula círculos inteiros para o projeto 1.","D":"243 m² também usa círculo inteiro para o projeto 2; além disso, esse projeto não é o mais econômico.","E":"As áreas não são iguais: a soma de quadrados de raios não é o quadrado da soma desses raios."},"takeaway":"Área circular depende do quadrado do raio. Unir larguras pode aumentar a área, mesmo mantendo a soma dos diâmetros.","key":"matematica:M365","area":"matematica","year":2025,"number":173,"answer":"A","subject":"Geometria plana","topic":"Áreas e perímetros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Questão anulada: equação das parcelas","steps":["O gabarito oficial registra esta questão como anulada. Não há letra válida e ela não deve compor a taxa de acerto.","Para estudar a modelagem, os valores das parcelas seriam 60 000/n e 60 000/(n + 6). A diferença proposta leva a 60 000/n − 60 000/(n + 6) = 500.","Multiplicando pelos denominadores: n(n + 6) = 720, ou n² + 6n − 720 = 0. As raízes são 24 e −30; o modelo admite n positivo de 24. Essa análise didática não restaura uma letra oficial nem atribui motivo à anulação."],"alternatives":{"A":"Para n = 18, a diferença entre 60 000/18 e 60 000/24 é aproximadamente R$ 833,33, não R$ 500.","B":"Para n = 24, o modelo fornece parcelas de R$ 2 500 e R$ 2 000. É uma verificação algébrica, não um gabarito oficial de item anulado.","C":"Para n = 30, as parcelas seriam R$ 2 000 e aproximadamente R$ 1 666,67, com diferença menor que R$ 500.","D":"Para n = 42, a diferença seria aproximadamente R$ 178,57, não o valor proposto.","E":"Para n = 48, a diferença seria aproximadamente R$ 138,89, também incompatível com a equação didática."},"takeaway":"Mesmo que seja possível resolver o modelo, respeite a situação oficial de anulação e não atribua uma letra como válida.","key":"matematica:M227","area":"matematica","year":2025,"number":174,"answer":"Anulada","subject":"Álgebra e Funções","topic":"Equações, sistemas e inequações","status":"verified","annulled":true,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Exatamente um dos dois presentes especiais","steps":["O filho mais velho deve receber exatamente um entre bicicleta e celular: há duas escolhas para esse presente especial.","Os outros dois presentes dele devem ser escolhidos entre os seis não especiais: C(6,2) = 15 maneiras.","Restam cinco presentes distintos; escolha três para o mais novo, C(5,3) = 10, ficando dois para o do meio. Total: 2 × 15 × 10 = 300, alternativa C."],"alternatives":{"A":"36 não contabiliza todas as escolhas dos dois presentes comuns do mais velho e da divisão restante.","B":"53 não resulta das escolhas independentes exigidas pela distribuição; não se somam etapas que devem ocorrer juntas.","C":"300 considera a escolha de um especial, dois comuns para o mais velho e três dos restantes para o mais novo.","D":"360 não corresponde ao produto 2 × C(6,2) × C(5,3); presentes dentro do mesmo conjunto não têm ordem.","E":"560 = C(8,3) × C(5,3) conta todas as distribuições por tamanho, incluindo as proibidas com ambos ou nenhum especial para o mais velho."},"takeaway":"“Um ou outro, mas não ambos” é escolha exclusiva. Depois de atender à restrição, distribua o restante por combinações.","key":"matematica:M751","area":"matematica","year":2025,"number":175,"answer":"C","subject":"Probabilidade e Análise combinatória","topic":"Contagem e análise combinatória","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Tempo efetivo de participação","steps":["O jogador entrou no início do segundo tempo, portanto jogou 45 minutos regulamentares e mais 30 de prorrogação, totalizando 75 minutos.","A velocidade média foi 4,5/45 = 0,1 km por minuto. Mantida na prorrogação, acrescenta 30 × 0,1 = 3 km.","A distância total é 4,5 + 3 = 7,5 km: C. Os primeiros 45 minutos da partida ocorreram sem sua participação."],"alternatives":{"A":"4,5 km considera somente o segundo tempo e omite a prorrogação de 30 minutos.","B":"6,0 km não corresponde aos 75 minutos jogados à taxa de 0,1 km/min.","C":"7,5 km somam os 4,5 km do segundo tempo aos 3 km da prorrogação.","D":"9,0 km corresponderiam a 90 minutos nessa velocidade, mais que os 75 efetivamente jogados.","E":"12,0 km usa os 120 minutos da partida inteira, incluindo o primeiro tempo em que o jogador não estava em campo."},"takeaway":"Em problemas de taxa, use o tempo de atuação do sujeito, não automaticamente a duração completa do evento.","key":"matematica:M005","area":"matematica","year":2025,"number":176,"answer":"C","subject":"Aritmética e Matemática básica","topic":"Razão, proporção e regra de três","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Volume de ouro na região entre círculo e quadrado","steps":["A medalha tem raio 3 cm. Com π ≈ 3,1, sua área circular é 3,1 × 3² = 27,9 cm².","O quadrado inscrito tem diagonal igual ao diâmetro, 6 cm, e área d²/2 = 18 cm². A área em ouro é 27,9 − 18 = 9,9 cm².","Converta 3 mm para 0,3 cm. Para cem medalhas: V = 9,9 × 0,3 × 100 = 297 cm³, alternativa B."],"alternatives":{"A":"288 cm³ não resulta da diferença de áreas com π = 3,1 e da espessura de 0,3 cm.","B":"297 cm³ correspondem à região circular externa ao prisma quadrado, multiplicada pela espessura e por cem medalhas.","C":"567 cm³ resultam de subtrair uma área quadrada de 9 cm², mas o quadrado tem diagonal 6 e área 18 cm².","D":"990 omite o fator da espessura de 0,3 cm ao multiplicar apenas a área de ouro por cem.","E":"1 134 cm³ excedem o volume correto; o ouro não ocupa o prisma central e o raio não é o diâmetro de 6 cm."},"takeaway":"Quadrado inscrito: diagonal = diâmetro da circunferência. Para volume, mantenha todas as medidas na mesma unidade.","key":"matematica:M438","area":"matematica","year":2025,"number":177,"answer":"B","subject":"Geometria espacial","topic":"Volumes e capacidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Vantagem de dois dados com empate desfavorável","steps":["Existem 6³ = 216 resultados ordenados equiprováveis. João vence quando seu número j é maior ou igual a cada dado de Artur.","Para j fixo, há j² pares possíveis de Artur que dão vitória a João. Somando: 1² + 2² + 3² + 4² + 5² + 6² = 91.","Assim P(João) = 91/216 e P(Artur) = 1 − 91/216 = 125/216. Artur tem a maior chance, como afirma E. A regra de empate já está incluída no sinal “maior ou igual”."],"alternatives":{"A":"Artur é favorecido, mas sua probabilidade não é simplesmente 2/3: a distribuição do máximo e os empates precisam ser contados.","B":"João tem 91/216, não 4/9, e sua chance é menor que a de Artur.","C":"91/216 é a chance de João, não a de Artur; a alternativa troca os eventos.","D":"A fração de João está correta, mas ele não é o jogador com a maior probabilidade, como pede o comando.","E":"Artur vence em 125 dos 216 resultados, mais que os 91 em que João vence, incluindo os empates."},"takeaway":"Contar o complementar pode ser mais simples: fixe o dado de um jogador e conte os pares que o outro precisa obter.","key":"matematica:M698","area":"matematica","year":2025,"number":178,"answer":"E","subject":"Probabilidade e Análise combinatória","topic":"Probabilidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Unidade de uma razão","steps":["O enunciado define a grandeza como intensidade luminosa dividida pelo quadrado da distância.","Substitua grandezas por unidades: [L] = cd/(m)² = cd/m².","A resposta é A. O expoente do denominador permanece na unidade; não se inverte a razão nem se eleva candela ao quadrado."],"alternatives":{"A":"cd/m² mantém intensidade luminosa no numerador e distância ao quadrado no denominador, conforme a definição.","B":"m²/cd é a unidade da razão inversa, não da grandeza definida.","C":"cd/m esquece o quadrado da distância, alterando a dimensão indicada.","D":"m/cd inverte a razão e também deixa de elevar a distância ao quadrado.","E":"m/cd² coloca o quadrado na grandeza errada e inverte a posição das unidades."},"takeaway":"A análise dimensional segue exatamente a fórmula fornecida, inclusive produtos, razões e expoentes.","key":"matematica:M117","area":"matematica","year":2025,"number":179,"answer":"A","subject":"Aritmética e Matemática básica","topic":"Escalas e conversões de unidades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ganho líquido em cada rodada","steps":["O jogador 1 entrega uma moeda ao jogador 2 e recebe quatro do jogador 4 a cada rodada completa.","Seu saldo por rodada é 4 − 1 = 3 moedas. Depois de n rodadas, acumulou ganho de 3n.","Como começou com 100 moedas, a expressão é 100 + 3n, alternativa D. Confira n = 0: ela retorna as cem iniciais."],"alternatives":{"A":"103 + 4n já altera a quantidade inicial e conta o recebimento de quatro sem descontar a moeda entregue.","B":"103 + 3n usa o saldo correto, mas acrescenta três moedas indevidamente no início, deslocando a contagem de rodadas.","C":"100 + 4n ignora a saída de uma moeda em cada rodada; o ganho líquido é três.","D":"100 + 3n combina as cem iniciais com três moedas líquidas ganhas por rodada completa.","E":"99 + 4n desconta a entrega apenas uma vez; o jogador perde uma moeda em todas as rodadas."},"takeaway":"Em fluxos repetidos, modele a variação líquida por etapa e teste a condição inicial antes de validar a fórmula.","key":"matematica:M323","area":"matematica","year":2025,"number":180,"answer":"D","subject":"Álgebra e Funções","topic":"Sequências, PA e PG","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2025.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
